using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json;using Orbit;
class MinecraftTests {
 static string root=Path.Combine(Path.GetTempPath(),"orbit-minecraft-"+Guid.NewGuid());static int n;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+(++n)+" "+name);}static void Fails(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception(name+" did not reject");}
 static string Dir(string path){var p=Path.Combine(root,path);Directory.CreateDirectory(p);return p;}
 static void Zip(string path,params string[] pairs){using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){for(int i=0;i<pairs.Length;i+=2)using(var w=new StreamWriter(z.CreateEntry(pairs[i]).Open()))w.Write(pairs[i+1]);}}
 static void Main(){Dir("");try{var prism=Dir("Prism Data");var instance=Dir("Prism Data/instances/Couple Pack");File.WriteAllText(Path.Combine(instance,"instance.cfg"),"[General]\nname=Our World\n[Other]\nname=Ignored\n");File.WriteAllText(Path.Combine(instance,"mmc-pack.json"),"{\"components\":[{\"uid\":\"net.minecraft\",\"version\":\"1.21.1\"},{\"uid\":\"net.fabricmc.fabric-loader\",\"version\":\"0.16.10\"}]}");
 var p=MinecraftFiles.PrismProfile(instance);Check(p.name=="Our World"&&p.version=="1.21.1"&&p.loader=="Fabric"&&p.launchable,"Prism version loader and name");Check(MinecraftFiles.InstancesRoot(prism)==Path.Combine(prism,"instances"),"default instances root");File.WriteAllText(Path.Combine(prism,"prismlauncher.cfg"),"[General]\nInstanceDir=custom\n");Check(MinecraftFiles.InstancesRoot(prism)==Path.Combine(prism,"custom"),"custom relative instances directory");File.Delete(Path.Combine(prism,"prismlauncher.cfg"));
 Check(MinecraftFiles.GameRoot(instance)==Path.Combine(instance,"minecraft"),"new instance game root");Directory.CreateDirectory(Path.Combine(instance,".minecraft"));Check(MinecraftFiles.GameRoot(instance).EndsWith(".minecraft"),"legacy dot minecraft");Directory.CreateDirectory(Path.Combine(instance,"minecraft"));Check(!MinecraftFiles.GameRoot(instance).EndsWith(".minecraft"),"regular minecraft wins when both exist");p=MinecraftFiles.PrismProfile(instance);
 var curse=Dir("CurseForge/Instances/CF Pack");File.WriteAllText(Path.Combine(curse,"minecraftinstance.json"),"{\"name\":\"CF World\",\"gameVersion\":\"1.20.1\",\"baseModLoader\":{\"name\":\"forge-47.3\"},\"installedAddons\":[{\"unused\":true}]}");var cp=MinecraftFiles.CurseProfile(curse);Check(cp.name=="CF World"&&cp.loader=="forge-47.3"&&!cp.launchable&&cp.gamePath==curse,"CurseForge detection without direct launch claim");
 var inbox=Dir("Downloads");var cf=Path.Combine(inbox,"CF.zip");Zip(cf,"manifest.json","{\"name\":\"Together\",\"minecraft\":{\"version\":\"1.20.1\"},\"files\":[]}");var mr=Path.Combine(inbox,"Fabric.mrpack");Zip(mr,"modrinth.index.json","{\"name\":\"Fabric Pack\",\"game\":\"minecraft\",\"dependencies\":{\"minecraft\":\"1.21.1\"},\"files\":[]}");var pp=Path.Combine(inbox,"Prism.zip");Zip(pp,"Pack/mmc-pack.json","{\"components\":[]}");Check(MinecraftFiles.Pack(cf).format=="CurseForge"&&MinecraftFiles.Pack(mr).format=="Modrinth"&&MinecraftFiles.Pack(pp).format=="Prism","three pack formats");
 var evil=Path.Combine(inbox,"unsafe.zip");Zip(evil,"manifest.json","{\"minecraft\":{},\"files\":[]}","../escape","bad");Fails(()=>MinecraftFiles.Pack(evil),"path traversal archive rejected");var absolute=Path.Combine(inbox,"absolute.zip");Zip(absolute,"/manifest.json","{}");Fails(()=>MinecraftFiles.Pack(absolute),"absolute archive entry rejected");var partial=Path.Combine(inbox,"partial.zip");File.WriteAllText(partial,"not finished");Fails(()=>MinecraftFiles.Pack(partial),"incomplete archive rejected");
 var scan=MinecraftFiles.Scan(new MinecraftSettings{prismRoot=prism,curseRoot=Path.Combine(root,"CurseForge"),packFolder=inbox});Check(scan.profiles.Count==2&&scan.packs.Count==3,"scan skips unsafe and incomplete downloads");
 var src=Dir("Mods");var fabric=Path.Combine(src,"fabric-test.jar");Zip(fabric,"fabric.mod.json","{}");var forge=Path.Combine(src,"forge-test.jar");Zip(forge,"META-INF/mods.toml","modLoader=javafml");MinecraftFiles.AddMods(p,new[]{fabric,forge});Check(MinecraftFiles.Mods(p).Count==2&&File.Exists(fabric),"batch copies mods and keeps sources");
 Fails(()=>MinecraftFiles.AddMods(p,new[]{fabric}),"existing mod not overwritten");MinecraftFiles.ToggleMod(p,"fabric-test.jar");Check(MinecraftFiles.Mods(p).First(m=>m.file.StartsWith("fabric")).enabled==false,"disable preserves jar as disabled");Fails(()=>MinecraftFiles.AddMods(p,new[]{fabric}),"disabled mod also protected");MinecraftFiles.ToggleMod(p,"fabric-test.jar.disabled");Check(MinecraftFiles.Mods(p).All(m=>m.enabled),"enable restores jar");
 Fails(()=>MinecraftFiles.ToggleMod(p,"../x.jar"),"toggle traversal rejected");var invalid=Path.Combine(src,"not-a-mod.jar");Zip(invalid,"hello.txt","x");Fails(()=>MinecraftFiles.AddMods(p,new[]{invalid}),"ordinary jar rejected");var fresh=Path.Combine(src,"new.jar");Zip(fresh,"fabric.mod.json","{}");Fails(()=>MinecraftFiles.AddMods(p,new[]{fresh,invalid}),"all files checked before copy");Check(!File.Exists(Path.Combine(MinecraftFiles.ModsRoot(p),"new.jar")),"failed batch leaves no partial mods");var vanilla=MinecraftFiles.PrismProfile(instance);vanilla.loader="Vanilla";Fails(()=>MinecraftFiles.AddMods(vanilla,new[]{fresh}),"vanilla requires loader");
 Directory.CreateSymbolicLink(Path.Combine(root,"symlink"),instance);Fails(()=>MinecraftFiles.PrismProfile(Path.Combine(root,"symlink")),"linked profile rejected");
 Check(MinecraftFiles.Quote("C:\\Games\\")=="\"C:\\Games\\\\\"","trailing backslash quoting");Check(MinecraftFiles.Quote("a\"b")=="\"a\\\"b\"","embedded quote escaping");Fails(()=>MinecraftFiles.Quote("a\nb"),"command controls rejected");Check(MinecraftFiles.PrismArguments(prism,"launch","Couple Pack").EndsWith("\"--launch=Couple Pack\""),"instance names with spaces stay one argument");Fails(()=>MinecraftFiles.PrismArguments(prism,"launch","../bad"),"launch instance path rejected");Fails(()=>MinecraftFiles.PrismArguments(prism,"unexpected","x"),"unknown CLI switch rejected");
 var settingsFile=Path.Combine(root,"settings.json");var store=new LocalDocument<MinecraftSettings>(settingsFile,65536,MinecraftFiles.ValidateSettings);store.Save(new MinecraftSettings{prismRoot=prism,askRadmin=false});var loaded=new LocalDocument<MinecraftSettings>(settingsFile,65536,MinecraftFiles.ValidateSettings);Check(loaded.Value.prismRoot==prism&&!loaded.Value.askRadmin,"settings persist");loaded.Save(new MinecraftSettings{prismRoot=prism});File.WriteAllText(settingsFile,"{\"schema\":2}");var future=new LocalDocument<MinecraftSettings>(settingsFile,65536,MinecraftFiles.ValidateSettings);Check(future.ReadOnly,"settings future schema never downgraded");Fails(()=>future.Save(new MinecraftSettings()),"future settings immutable");
 Check(!Directory.GetDirectories(root,".orbit-import-*",SearchOption.AllDirectories).Any(),"no staging folders remain");Console.WriteLine("MinecraftTests: "+n+" passed");}finally{Directory.Delete(root,true);}}
}
